/**
 * The canonical solids of the polyhedra space: the 5 Platonic, 13 Archimedean and 13 Catalan solids,
 * 5 prisms, 5 antiprisms and 15 elongated prisms of upstream's catalogue (alejandrozu/platonic-packing,
 * MIT, src/solids_exact.json; see THIRD_PARTY_NOTICES.md), then PolyPack's prisms and antiprisms with 7, 9,
 * 10 and 11 sides and their 12 elongated prisms, in upstream's conventions. Coordinates come from the exact ones
 * (solids.data.ts, generated by python/polyhedra/gen_solids.py), each rounded to the nearest binary64.
 *
 * Conventions (upstream's):
 *  - every solid is centred at the origin (its vertex centroid, which is interior);
 *  - Platonic and Archimedean solids, prisms and antiprisms have edges of length 1; elongated prisms
 *    have base edges 1 and lateral edges 1.5, 2 or 3; Catalan solids are the polar reciprocals of the
 *    unit-edge Archimedean solids about the midsphere (their edges are not 1);
 *  - faces are vertex cycles ordered counter-clockwise seen from outside; face f is the plane
 *    normals[f] . x = offsets[f] with a unit outward normal, and the solid is the intersection of
 *    the half-spaces normals[f] . x <= offsets[f].
 */
import { SOLID_DATA, type SolidData } from "./solids.data";

export type SolidFamily = SolidData["family"];

export interface Solid {
  /** Upstream's name, e.g. "truncated_tetrahedron", "prism3_l15". */
  name: string;
  /** Upstream's three-to-five letter code, e.g. "tte", "pr3l15". */
  code: string;
  family: SolidFamily;
  /** Plain name, e.g. "truncated tetrahedron", "triangular prism of height 1.5". */
  title: string;
  /** Vertices, flat [x0, y0, z0, x1, ...]. */
  V: Float64Array;
  nv: number;
  faces: number[][];
  /** Unit outward face normals, flat [n0x, n0y, n0z, ...]. */
  N: Float64Array;
  /** Face offsets: face f is N_f . x = offsets[f]. */
  offsets: Float64Array;
  edges: [number, number][];
  /** The two faces of each edge (same order as edges). */
  edgeFaces: [number, number][];
  /** Smallest face offset: the radius of the largest ball about the centre inside the solid. */
  inradius: number;
  /** Largest vertex distance from the centre. */
  circumradius: number;
  volume: number;
  /** True when every face is at the same distance from the centre (an insphere touches every face). */
  tangential: boolean;
  /** Longest edge. */
  edgeMax: number;
}

function prepare(d: SolidData): Solid {
  const nv = d.V.length;
  const V = new Float64Array(3 * nv);
  d.V.forEach((v, i) => V.set(v, 3 * i));
  const N = new Float64Array(3 * d.faces.length);
  d.normals.forEach((n, f) => N.set(n, 3 * f));
  const key = (a: number, b: number) => (a < b ? a * 4096 + b : b * 4096 + a);
  const faceOf = new Map<number, number[]>();
  d.faces.forEach((f, fi) =>
    f.forEach((a, t) => {
      const k = key(a, f[(t + 1) % f.length]);
      const list = faceOf.get(k) ?? [];
      list.push(fi);
      faceOf.set(k, list);
    }),
  );
  const edgeFaces = d.edges.map(([i, j]): [number, number] => {
    const l = faceOf.get(key(i, j));
    if (!l || l.length !== 2) throw new Error(`${d.name}: edge ${i}-${j} is not on two faces`);
    return [l[0], l[1]];
  });
  let edgeMax = 0;
  for (const [i, j] of d.edges)
    edgeMax = Math.max(edgeMax, Math.hypot(V[3 * j] - V[3 * i], V[3 * j + 1] - V[3 * i + 1], V[3 * j + 2] - V[3 * i + 2]));
  return {
    name: d.name,
    code: d.code,
    family: d.family,
    title: d.title,
    V,
    nv,
    faces: d.faces,
    N,
    offsets: Float64Array.from(d.offsets),
    edges: d.edges,
    edgeFaces,
    inradius: d.inradius,
    circumradius: d.circumradius,
    volume: d.volume,
    tangential: d.tangential,
    edgeMax,
  };
}

const SOLIDS = new Map<string, Solid>();
const BY_CODE = new Map<string, string>();
for (const d of SOLID_DATA) BY_CODE.set(d.code, d.name);

/**
 * Every solid's name: upstream's 56 in upstream's order (Platonic, Archimedean, Catalan, prisms, antiprisms,
 * elongated prisms), then PolyPack's 20 (prisms, antiprisms, elongated prisms with 7, 9, 10 and 11 sides).
 */
export const SOLID_NAMES: readonly string[] = SOLID_DATA.map((d) => d.name);

export function isSolidName(v: unknown): v is string {
  return typeof v === "string" && SOLID_NAMES.includes(v);
}

/** The solid of a name, prepared once and cached. */
export function getSolid(name: string): Solid {
  let s = SOLIDS.get(name);
  if (!s) {
    const d = SOLID_DATA.find((x) => x.name === name);
    if (!d) throw new Error(`unknown solid ${name}`);
    s = prepare(d);
    SOLIDS.set(name, s);
  }
  return s;
}

/** The solid's name from its code ("tte" -> "truncated_tetrahedron"), or null. */
export function solidNameOfCode(code: string): string | null {
  return BY_CODE.get(code) ?? null;
}
